$ErrorActionPreference='Stop'
$root=(Get-Location).Path
$html=Get-Content (Join-Path $root 'docs\보고서\Kanto_페이지별_팀원_기여도.html') -Raw -Encoding UTF8
$m=[regex]::Match($html,'const data=(\[[\s\S]*?\n\]);\nfunction avg');$data=$m.Groups[1].Value|ConvertFrom-Json
$names=@('김도혁','박소유','이동근','임태형');$hex=@('3158A5','EF7B45','39A57B','8B61C2')
function Rgb([string]$h){$r=[convert]::ToInt32($h.Substring(0,2),16);$g=[convert]::ToInt32($h.Substring(2,2),16);$b=[convert]::ToInt32($h.Substring(4,2),16);return $r+256*$g+65536*$b}
function Text($slide,$text,$x,$y,$w,$h,$size,$bold=$false,$color='172038'){$s=$slide.Shapes.AddTextbox(1,$x,$y,$w,$h);$s.TextFrame.TextRange.Text=$text;$s.TextFrame.TextRange.Font.Name='맑은 고딕';$s.TextFrame.TextRange.Font.Size=$size;$s.TextFrame.TextRange.Font.Bold=[int]$bold;$s.TextFrame.TextRange.Font.Color.RGB=(Rgb $color);$s.TextFrame.MarginLeft=0;$s.TextFrame.MarginRight=0;return $s}
