$s=$pres.Slides.Add(1,12);$bg=$s.Background.Fill;$bg.ForeColor.RGB=(Rgb '17264A');$bg.Solid();Text $s 'KANTO PROJECT · CONTRIBUTION REPORT' 55 120 700 30 12 $true '9EBCFF'|Out-Null;Text $s "페이지별 팀원 기여도`n분석 보고서" 55 165 700 110 32 $true 'FFFFFF'|Out-Null;Text $s '기능 구현 · 디자인/UI · 추가 개선 항목별 기여율' 55 300 700 35 16 $false 'D7E2FF'|Out-Null;Text $s '대상: 김도혁 · 박소유 · 이동근 · 임태형  |  작성일: 2026. 07. 07.' 55 430 700 25 10 $false 'AEC2EE'|Out-Null
$s=$pres.Slides.Add(2,12);Text $s '산정 기준 및 해석 방법' 50 45 740 45 25 $true|Out-Null;Text $s "근거 자료`n팀원별 활동 보고서·정리 Excel 4종, 전체 Git 이력, 주도 PR 목록, WBS 담당 기록을 함께 사용했습니다.`n`n비율 산정`n기능영역별 비병합 커밋과 작업 유형을 기본 점수로 삼고, 단독 주도 기능 및 현재 코드에 남은 구현을 보정했습니다.`n`n항목 정의`n기능 구현: 신규 기능·데이터 연동`n디자인/UI: 레이아웃·반응형·접근성`n추가 개선: 버그·성능·리팩터링·보안" 55 120 720 300 15 $false '4C5870'|Out-Null;Text $s '주의: 본 수치는 노동시간이 아니라 저장소에서 확인 가능한 결과물 기준의 상대 기여 추정치입니다.' 55 480 720 35 11 $false '7A8498'|Out-Null
$n=3
foreach($d in $data){$s=$pres.Slides.Add($n,12);Text $s ("PAGE {0:D2}" -f ($n-2)) 50 30 150 20 9 $true '5873AD'|Out-Null;Text $s ([string]$d[0]) 50 53 600 42 24 $true|Out-Null;Text $s ([string]$d[1]) 620 60 170 20 8 $false '69758C'|Out-Null;Text $s ([string]$d[2]) 50 112 490 55 12 $false '4C5870'|Out-Null;$rows=$d[3];$tot=@(0,0,0,0);$y=188;foreach($key in @('기능 구현','디자인/UI','추가 개선')){Text $s $key 50 $y 180 25 14 $true|Out-Null;$vals=@($rows.$key);$parts=@();for($i=0;$i -lt 4;$i++){$parts+="$($names[$i])  $($vals[$i])%";$tot[$i]+=[int]$vals[$i]};Text $s ($parts -join '     ') 50 ($y+30) 510 30 11 $false '284B93'|Out-Null;$y+=88};for($i=0;$i -lt 4;$i++){$tot[$i]=[math]::Round($tot[$i]/3)};$chart=Join-Path $root ('.tmp-contribution-charts\chart-{0:D2}.png' -f $n);$s.Shapes.AddPicture($chart,0,-1,585,160,190,190)|Out-Null;Text $s '페이지 종합 기여도' 595 128 170 25 13 $true|Out-Null;$ly=372;for($i=0;$i -lt 4;$i++){$dot=$s.Shapes.AddShape(9,600,$ly,10,10);$dot.Fill.ForeColor.RGB=(Rgb $hex[$i]);$dot.Line.Visible=0;Text $s ("{0}     {1}%" -f $names[$i],$tot[$i]) 620 ($ly-4) 140 20 11 $true|Out-Null;$ly+=28};Text $s '근거: 팀원별 활동 보고서·Git·PR·WBS / 반올림으로 합계에 ±1% 오차 가능' 50 555 650 18 8 $false '7A8498'|Out-Null;$n++}
